%[text] # **Nonlinear Dynamic MATLAB Substructure**
%[text] A Duffing oscillator is represented by a callback substructure that returns force, tangent, mass, and damping. An independent ODE solution checks both the callback implementation and the OpenSees transient analysis.
%[text] The physical system is a MATLAB-backed nonlinear substructure under sinusoidal loading.
%[text] The physical system is a single-degree-of-freedom Duffing oscillator:
%[text] \\$\\$mu'' + cu' + k u + \\alpha u^3 = P\_0 \\sin(\\omega t)\\$\\$
%[text] OpenSees performs the transient analysis using the Newmark method. The MATLAB callback returns the nonlinear internal force, consistent tangent stiffness, mass matrix, and damping matrix.
%[text] An independent [ode45 - Solve nonstiff differential equations — medium order method - MATLAB](https://www.mathworks.com/help/matlab/ref/ode45.html) solution is used as a reference.
%[text] ### Define the oscillator and loading history
%[text] `K0`, `M0`, and `C0` use the same two-interface-DOF ordering. Physical mass and damping are supplied by the callback and must not also be assigned with `mass` or Rayleigh damping.
clc; clear; close all;
% Model parameters
m = 2.0;
c = 1.5;
k = 400.0;
alpha = 2.0e6;

P0 = 20.0;
frequency = 2.0;
omega = 2*pi*frequency;

dt = 0.001;
duration = 5.0;
nSteps = round(duration/dt);

time = (0:nSteps).' * dt;
loadValues = P0*sin(omega*time);

K0 = k * [
     1 -1
    -1  1
];

% Only node 2 carries physical mass and damping.
M0 = [
    0 0
    0 m
];

C0 = [
    0 0
    0 c
];

initialState = struct( ...
    "k", k, ...
    "alpha", alpha, ...
    "M", M0, ...
    "C", C0);
%[text] ### Create the callback-backed substructure
%[text] Node 1 is fixed and node 2 carries the oscillator response. The callback evaluates (ku+\\alpha u^3), its consistent tangent, and the constant mass and damping matrices.
%% Create the OpenSees command interface

opsMAT = OpenSeesMatlab();
ops = opsMAT.opensees;

% Remove a model left by an earlier run.
ops.wipe();

% Automatically clean up if the script stops because of an error.
cleanupGuard = onCleanup( ...
    @() cleanupNonlinearDynamicModel(ops));
%% Create nodes and boundary conditions
%
%   fixed node 1 ---- nonlinear substructure ---- node 2
%
% Both nodes have one translational DOF.

ops.model("basic", "-ndm", 1, "-ndf", 1);

ops.node(1, 0.0);
ops.node(2, 1.0);

ops.fix(1, 1);
%% Define the interface
% Each row is:
%
%   [nodeTag, oneBasedDOF]
%
% The row order defines trial.disp, trial.vel, trial.accel,
% response.force, and all returned matrix rows and columns.

interfacePairs = [
    1 1
    2 1
];

eleTag = 2001;

ops.callbackSubstructure( ...
    eleTag, ...
    @duffingSubstructureCallback, ...
    initialState, ...
    K0, ...
    interfacePairs, ...
    "tangentMode", "matlab");

% Do not also assign mass m using ops.mass(). The physical mass is already
% returned by the MATLAB callback.
%[text] ### Apply the sinusoidal force
%[text] The `Path` series already includes its value at time zero, so no extra leading zero is inserted. A unit nodal load lets the time-series value act directly as the applied force.
%% Create the sinusoidal external load
% loadValues already contains the value at t = 0. Therefore,
% "-prependZero" must not be used, or the loading history will be shifted
% by one time step.

timeSeriesTag = 1;
patternTag = 1;

ops.timeSeries( ...
    "Path", ...
    timeSeriesTag, ...
    "-dt", dt, ...
    "-values", loadValues.');

ops.pattern( ...
    "Plain", ...
    patternTag, ...
    timeSeriesTag);

% A unit reference load is multiplied by the Path time-series factor.
ops.load(2, 1.0);
%% Configure the nonlinear transient analysis

ops.constraints("Plain");
ops.numberer("Plain");
ops.system("BandGeneral");

ops.test( ...
    "EnergyIncr", ...
    1.0e-12, ...
    30);

ops.algorithm("Newton");

% Average-acceleration Newmark method.
gamma = 0.5;
beta = 0.25;

ops.integrator( ...
    "Newmark", ...
    gamma, ...
    beta);

ops.analysis("Transient");

%% Allocate response arrays

uOpenSees = zeros(nSteps + 1, 1);
vOpenSees = zeros(nSteps + 1, 1);
aOpenSees = zeros(nSteps + 1, 1);
forceOpenSees = zeros(nSteps + 1, 1);

analysisStatus = zeros(nSteps, 1);

% Initial nodal response.
uOpenSees(1) = ops.nodeDisp(2, 1);
vOpenSees(1) = ops.nodeVel(2, 1);
aOpenSees(1) = ops.nodeAccel(2, 1);

% The Element may not have been initialized before the first analysis
% update. The initial nonlinear elastic force is zero for this example.
forceOpenSees(1) = 0.0;

%[text] ### Integrate the OpenSees response
%[text] Average-acceleration Newmark advances one step at a time. Nodal displacement, velocity, acceleration, and callback resisting force are stored only after a converged step.
%% Run the transient analysis
% One time step can contain several callback evaluations. The callback must
% therefore calculate every trial from committedState.

failedStep = 0;

for step = 1:nSteps

    analysisStatus(step) = ops.analyze(1, dt);

    if analysisStatus(step) ~= 0
        failedStep = step;
        break
    end

    index = step + 1;

    uOpenSees(index) = ops.nodeDisp(2, 1);
    vOpenSees(index) = ops.nodeVel(2, 1);
    aOpenSees(index) = ops.nodeAccel(2, 1);

    interfaceForce = ops.eleResponse( ...
        eleTag, ...
        "interfaceForce");

    forceOpenSees(index) = interfaceForce(end);
end

if failedStep ~= 0
    error( ...
        "The nonlinear transient analysis failed at step %d, time %.6f s.", ...
        failedStep, ...
        failedStep*dt);
end
%[text] ### Compare with an independent ODE solution
%[text] `ode45` solves the same scalar equation without the OpenSees element or callback machinery. Agreement therefore checks the force law, tangent, mass, damping, loading phase, and transient integration together.
%% Independent ode45 reference solution
% Solve:
%
%   m*u'' + c*u' + k*u + alpha*u^3 = P0*sin(omega*t)

odeFunction = @(t,y) [
    y(2)
    (P0*sin(omega*t) ...
        - c*y(2) ...
        - k*y(1) ...
        - alpha*y(1)^3) / m
];

odeOptions = odeset( ...
    "RelTol", 1.0e-10, ...
    "AbsTol", 1.0e-12);

initialConditions = [
    0
    0
];

[timeReference, stateReference] = ode45( ...
    odeFunction, ...
    time, ...
    initialConditions, ...
    odeOptions);

uReference = stateReference(:,1);
vReference = stateReference(:,2);

aReference = ( ...
    loadValues ...
    - c*vReference ...
    - k*uReference ...
    - alpha*uReference.^3) / m;

% The Element interface force excludes the separately assembled C*v term.
forceReference = ...
    k*uReference + alpha*uReference.^3;
%% Calculate verification errors

displacementDifference = ...
    uOpenSees - uReference;

velocityDifference = ...
    vOpenSees - vReference;

accelerationDifference = ...
    aOpenSees - aReference;

forceDifference = ...
    forceOpenSees - forceReference;

maxDisplacementError = ...
    max(abs(displacementDifference));

rmsDisplacementError = ...
    sqrt(mean(displacementDifference.^2));

maxVelocityError = ...
    max(abs(velocityDifference));

rmsVelocityError = ...
    sqrt(mean(velocityDifference.^2));

maxAccelerationError = ...
    max(abs(accelerationDifference));

rmsAccelerationError = ...
    sqrt(mean(accelerationDifference.^2));

maxForceError = ...
    max(abs(forceDifference));

rmsForceError = ...
    sqrt(mean(forceDifference.^2));

maxDisplacement = ...
    max(abs(uOpenSees));

maxVelocity = ...
    max(abs(vOpenSees));

maxAcceleration = ...
    max(abs(aOpenSees));

maxRestoringForce = ...
    max(abs(forceOpenSees));

displacementScale = ...
    max(max(abs(uReference)), 1.0e-12);

forceScale = ...
    max(max(abs(forceReference)), 1.0e-12);

relativeDisplacementError = ...
    maxDisplacementError / displacementScale;

relativeForceError = ...
    maxForceError / forceScale;
%% Verify the numerical agreement
% Newmark and ode45 use different integration methods, so their solutions
% are not expected to be identical.

absoluteDisplacementTolerance = 2.0e-4;
relativeDisplacementTolerance = 1.0e-2;

verificationPassed = ...
    maxDisplacementError <= absoluteDisplacementTolerance || ...
    relativeDisplacementError <= relativeDisplacementTolerance;

if ~verificationPassed

    errorMessage = sprintf( ...
        "Displacement verification failed.\n" + ...
        "Maximum absolute error: %.6e\n" + ...
        "Maximum reference response: %.6e\n" + ...
        "Relative error: %.6e\n" + ...
        "Absolute tolerance: %.6e\n" + ...
        "Relative tolerance: %.6e", ...
        maxDisplacementError, ...
        displacementScale, ...
        relativeDisplacementError, ...
        absoluteDisplacementTolerance, ...
        relativeDisplacementTolerance);

    error("%s", errorMessage);
end

%% Read callback statistics

trialCalls = ops.eleResponse( ...
    eleTag, ...
    "trialCallCount");

totalCalls = ops.eleResponse( ...
    eleTag, ...
    "callCount");

commitCount = ops.eleResponse( ...
    eleTag, ...
    "commitCount");

totalCallbackTime = ops.eleResponse( ...
    eleTag, ...
    "callbackTime");

meanCallbackTime = ops.eleResponse( ...
    eleTag, ...
    "meanCallbackTime");

maxCallbackTime = ops.eleResponse( ...
    eleTag, ...
    "maxCallbackTime");

%% Print one consolidated report

reportFormat = ...
    "\n" + ...
    "============================================================\n" + ...
    " Nonlinear Dynamic MATLAB Substructure Verification\n" + ...
    "============================================================\n" + ...
    "System parameters\n" + ...
    "  Mass                         : %.6g\n" + ...
    "  Damping                      : %.6g\n" + ...
    "  Linear stiffness             : %.6g\n" + ...
    "  Cubic stiffness              : %.6g\n" + ...
    "  Force amplitude              : %.6g\n" + ...
    "  Loading frequency            : %.6g Hz\n" + ...
    "  Time step                    : %.6g s\n" + ...
    "  Duration                     : %.6g s\n" + ...
    "  Number of steps              : %d\n" + ...
    "\n" + ...
    "Peak OpenSees response\n" + ...
    "  Maximum |displacement|       : %.6e\n" + ...
    "  Maximum |velocity|           : %.6e\n" + ...
    "  Maximum |acceleration|       : %.6e\n" + ...
    "  Maximum |restoring force|    : %.6e\n" + ...
    "\n" + ...
    "OpenSees versus ode45\n" + ...
    "  Maximum displacement error   : %.6e\n" + ...
    "  RMS displacement error       : %.6e\n" + ...
    "  Relative displacement error  : %.6e\n" + ...
    "  Maximum velocity error       : %.6e\n" + ...
    "  RMS velocity error           : %.6e\n" + ...
    "  Maximum acceleration error   : %.6e\n" + ...
    "  RMS acceleration error       : %.6e\n" + ...
    "  Maximum force error          : %.6e\n" + ...
    "  RMS force error              : %.6e\n" + ...
    "  Relative force error         : %.6e\n" + ...
    "\n" + ...
    "Callback statistics\n" + ...
    "  Trial calls                  : %.0f\n" + ...
    "  Total calls                  : %.0f\n" + ...
    "  Committed steps              : %.0f\n" + ...
    "  Total callback time          : %.6e s\n" + ...
    "  Mean callback time           : %.6e s\n" + ...
    "  Maximum callback time        : %.6e s\n" + ...
    "\n" + ...
    "Verification status            : PASSED\n" + ...
    "============================================================\n";

report = sprintf( ...
    reportFormat, ...
    m, ...
    c, ...
    k, ...
    alpha, ...
    P0, ...
    frequency, ...
    dt, ...
    duration, ...
    nSteps, ...
    maxDisplacement, ...
    maxVelocity, ...
    maxAcceleration, ...
    maxRestoringForce, ...
    maxDisplacementError, ...
    rmsDisplacementError, ...
    relativeDisplacementError, ...
    maxVelocityError, ...
    rmsVelocityError, ...
    maxAccelerationError, ...
    rmsAccelerationError, ...
    maxForceError, ...
    rmsForceError, ...
    relativeForceError, ...
    trialCalls, ...
    totalCalls, ...
    commitCount, ...
    totalCallbackTime, ...
    meanCallbackTime, ...
    maxCallbackTime);

fprintf("%s", report); %[output:8613a300]
%% Plot the results

f=figure( ... %[output:92c4747a]
    "Name", ... %[output:92c4747a]
    "Nonlinear Dynamic Substructure Verification", ... %[output:92c4747a]
    "Color", ... %[output:92c4747a]
    "w"); %[output:92c4747a]
f.Position = [100 200 1000 800]; %[output:92c4747a]

tiledlayout( ... %[output:92c4747a]
    3, ... %[output:92c4747a]
    2, ... %[output:92c4747a]
    "TileSpacing", ... %[output:92c4747a]
    "compact", ... %[output:92c4747a]
    "Padding", ... %[output:92c4747a]
    "compact"); %[output:92c4747a]

% Sinusoidal loading
nexttile; %[output:92c4747a]

plot( ... %[output:92c4747a]
    time, ... %[output:92c4747a]
    loadValues, ... %[output:92c4747a]
    "k-", ... %[output:92c4747a]
    "LineWidth", ... %[output:92c4747a]
    1.2); %[output:92c4747a]

grid on; %[output:92c4747a]
box on; %[output:92c4747a]

xlabel("Time (s)"); %[output:92c4747a]
ylabel("Applied force"); %[output:92c4747a]
title("Sinusoidal loading"); %[output:92c4747a]

% Displacement comparison
nexttile; %[output:92c4747a]

plot( ... %[output:92c4747a]
    time, ... %[output:92c4747a]
    uOpenSees, ... %[output:92c4747a]
    "b-", ... %[output:92c4747a]
    "LineWidth", ... %[output:92c4747a]
    1.4); %[output:92c4747a]

hold on; %[output:92c4747a]

plot( ... %[output:92c4747a]
    timeReference, ... %[output:92c4747a]
    uReference, ... %[output:92c4747a]
    "r--", ... %[output:92c4747a]
    "LineWidth", ... %[output:92c4747a]
    1.1); %[output:92c4747a]

hold off; %[output:92c4747a]
grid on; %[output:92c4747a]
box on; %[output:92c4747a]

xlabel("Time (s)"); %[output:92c4747a]
ylabel("Displacement"); %[output:92c4747a]
title("Displacement response"); %[output:92c4747a]

legend( ... %[output:92c4747a]
    "OpenSees Newmark", ... %[output:92c4747a]
    "ode45 reference", ... %[output:92c4747a]
    "Location", ... %[output:92c4747a]
    "bestoutside"); %[output:92c4747a]

% Displacement difference
nexttile; %[output:92c4747a]

plot( ... %[output:92c4747a]
    time, ... %[output:92c4747a]
    displacementDifference, ... %[output:92c4747a]
    "k-", ... %[output:92c4747a]
    "LineWidth", ... %[output:92c4747a]
    1.1); %[output:92c4747a]

grid on; %[output:92c4747a]
box on; %[output:92c4747a]

xlabel("Time (s)"); %[output:92c4747a]
ylabel("Displacement difference"); %[output:92c4747a]
title("OpenSees minus ode45"); %[output:92c4747a]

% Velocity comparison
nexttile; %[output:92c4747a]

plot( ... %[output:92c4747a]
    time, ... %[output:92c4747a]
    vOpenSees, ... %[output:92c4747a]
    "b-", ... %[output:92c4747a]
    "LineWidth", ... %[output:92c4747a]
    1.2); %[output:92c4747a]

hold on; %[output:92c4747a]

plot( ... %[output:92c4747a]
    timeReference, ... %[output:92c4747a]
    vReference, ... %[output:92c4747a]
    "r--", ... %[output:92c4747a]
    "LineWidth", ... %[output:92c4747a]
    1.0); %[output:92c4747a]

hold off; %[output:92c4747a]
grid on; %[output:92c4747a]
box on; %[output:92c4747a]

xlabel("Time (s)"); %[output:92c4747a]
ylabel("Velocity"); %[output:92c4747a]
title("Velocity response"); %[output:92c4747a]

legend( ... %[output:92c4747a]
    "OpenSees Newmark", ... %[output:92c4747a]
    "ode45 reference", ... %[output:92c4747a]
    "Location", ... %[output:92c4747a]
    "bestoutside"); %[output:92c4747a]

% Nonlinear force-displacement relation
nexttile; %[output:92c4747a]

plot( ... %[output:92c4747a]
    uOpenSees, ... %[output:92c4747a]
    forceOpenSees, ... %[output:92c4747a]
